<script setup lang="ts">
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import FieldError from '../../../components/FieldError.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface ReturnItem { id: string; order_item_id: string; product_variant_id: string | null; product_name: string; variant_name: string | null; sku: string; ordered_quantity: number; fulfilled_quantity: number; returnable_quantity: number; requested_quantity: number; received_quantity: number; accepted_quantity: number; restocked_quantity: number; reason: string | null; condition: string | null; disposition: string | null; inspection_notes: string | null; inspected_at: string | null }
interface History { id: string; from_status: string | null; to_status: string; reason: string | null; actor: string | null; created_at: string | null }
interface ReturnRecord { id: string; short_id: string; status: string; reason: string | null; notes: string | null; rejection_reason: string | null; cancellation_reason: string | null; requested_at: string | null; approved_at: string | null; rejected_at: string | null; received_at: string | null; inspection_started_at: string | null; completed_at: string | null; cancelled_at: string | null; order: { id: string; order_number: string; customer_id: string | null; customer_name: string; email: string | null; phone: string | null }; items: ReturnItem[]; history: History[] }
interface Refund { id: string; status: string; amount: string; currency: string; reason: string; completed_at: string | null; created_at: string | null }
interface Exchange { id: string; short_id: string; status: string; item_count: number; approved_at: string | null; completed_at: string | null; cancelled_at: string | null; created_at: string | null }
interface Location { id: string; name: string; code: string }
interface ReplacementVariant { id: string; product_name: string; name: string | null; sku: string }
interface Capabilities { manage: boolean; inspect: boolean; restock: boolean; view_refunds: boolean; manage_exchanges: boolean; approve: boolean; reject: boolean; receive: boolean; complete: boolean; cancel: boolean; create_exchange: boolean }
const props = defineProps<{ return: ReturnRecord; refunds: Refund[] | null; exchanges: Exchange[]; locations: Location[]; replacementVariants: ReplacementVariant[]; conditions: string[]; dispositions: string[]; capabilities: Capabilities }>();
const returnRequest = computed(() => props.return);
const page = usePage<PageProps>();
const status = computed(() => page.props.status);
const serverErrors = computed(() => page.props.errors as Record<string, string | undefined>);
const approveForm = useForm({});
const completeForm = useForm({});
const rejectForm = useForm({ reason: '' });
const cancelForm = useForm({ reason: '' });
const receiveForm = useForm<{ items: { return_item_id: string; quantity: number }[] }>({ items: props.return.items.map((item) => ({ return_item_id: item.id, quantity: item.requested_quantity })) });
const inspectForms = Object.fromEntries(props.return.items.map((item) => [item.id, useForm({ condition: item.condition ?? props.conditions[0] ?? '', disposition: item.disposition ?? props.dispositions[0] ?? '', accepted_quantity: item.inspected_at ? item.accepted_quantity : item.received_quantity, notes: item.inspection_notes ?? '' })]));
const restockForms = Object.fromEntries(props.return.items.map((item) => [item.id, useForm({ inventory_location_id: props.locations[0]?.id ?? '', quantity: Math.max(item.accepted_quantity - item.restocked_quantity, 0) })]));
const exchangeForm = useForm<{ items: { return_item_id: string; replacement_product_variant_id: string; quantity: number }[] }>({ items: props.return.items.filter((item) => item.accepted_quantity > 0).map((item) => ({ return_item_id: item.id, replacement_product_variant_id: props.replacementVariants[0]?.id ?? '', quantity: item.accepted_quantity })) });
const errorFor = (errors: Record<string, string | undefined>, ...keys: string[]) => keys.map((key) => errors[key]).find(Boolean);
const approve = () => approveForm.post(`/admin/returns/${props.return.id}/approve`, { preserveScroll: true });
const complete = () => completeForm.post(`/admin/returns/${props.return.id}/complete`, { preserveScroll: true });
const reject = () => { if (window.confirm('Reject this return request?')) rejectForm.post(`/admin/returns/${props.return.id}/reject`, { preserveScroll: true }); };
const cancel = () => { if (window.confirm('Cancel this return?')) cancelForm.post(`/admin/returns/${props.return.id}/cancel`, { preserveScroll: true }); };
const receive = () => receiveForm.post(`/admin/returns/${props.return.id}/receive`, { preserveScroll: true });
const inspect = (item: ReturnItem) => inspectForms[item.id].post(`/admin/return-items/${item.id}/inspect`, { preserveScroll: true });
const restock = (item: ReturnItem) => restockForms[item.id].post(`/admin/return-items/${item.id}/restock`, { preserveScroll: true });
const createExchange = () => exchangeForm.post(`/admin/returns/${props.return.id}/exchanges`, { preserveScroll: true });
</script>

<template>
    <Head :title="`Return ${returnRequest.short_id}`" />
    <AdminLayout><section>
        <div class="flex flex-wrap items-end justify-between gap-5"><div><Link href="/admin/returns" class="text-sm font-semibold text-emerald-800">Back to returns</Link><p class="mt-7 font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">{{ returnRequest.status }} / return {{ returnRequest.short_id }}</p><h1 class="mt-3 text-4xl font-semibold tracking-[-0.04em] sm:text-6xl">{{ returnRequest.order.order_number }}</h1><p class="mt-3 break-all font-mono text-xs text-[#637067]">{{ returnRequest.id }}</p></div><Link :href="`/admin/orders/${returnRequest.order.id}`" class="border border-[#17211b] px-4 py-3 text-sm font-semibold">Open order</Link></div>
        <p v-if="status" class="mt-6 border border-emerald-700 bg-emerald-50 p-4 text-sm font-semibold text-emerald-900">{{ status }}</p>
        <div v-if="capabilities.approve || capabilities.complete" class="mt-6 flex flex-wrap gap-3"><button v-if="capabilities.approve" :disabled="approveForm.processing" class="bg-[#17211b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40" @click="approve">Approve return</button><button v-if="capabilities.complete" :disabled="completeForm.processing" class="border border-emerald-800 px-5 py-3 text-sm font-semibold text-emerald-900 disabled:opacity-40" @click="complete">Complete return</button></div><FieldError :message="serverErrors.return ?? serverErrors.items" />
        <div class="mt-8 grid gap-5 sm:grid-cols-3"><article class="border bg-white p-5"><p class="text-xs uppercase text-[#637067]">Customer</p><p class="mt-2 font-semibold">{{ returnRequest.order.customer_name }}</p><p class="text-sm text-[#637067]">{{ returnRequest.order.email ?? 'No email' }}<br>{{ returnRequest.order.phone ?? 'No phone' }}</p></article><article class="border bg-white p-5"><p class="text-xs uppercase text-[#637067]">Reason</p><p class="mt-2">{{ returnRequest.reason ?? 'No overall reason provided' }}</p></article><article class="border bg-white p-5"><p class="text-xs uppercase text-[#637067]">Requested</p><p class="mt-2 font-semibold">{{ returnRequest.requested_at ? new Date(returnRequest.requested_at).toLocaleString() : '—' }}</p><p class="text-sm text-[#637067]">{{ returnRequest.items.length }} item lines</p></article></div>

        <form v-if="capabilities.receive" class="mt-10 border border-emerald-800/30 bg-emerald-50 p-6" @submit.prevent="receive"><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Inbound count</p><h2 class="mt-2 text-2xl font-semibold">Receive return</h2><div class="mt-5 grid gap-3"><label v-for="(item, index) in returnRequest.items" :key="item.id" class="grid items-center gap-3 text-sm sm:grid-cols-[1fr_7rem]"><span><strong>{{ item.product_name }}</strong><br><span class="text-xs text-[#637067]">{{ item.sku }} / {{ item.requested_quantity }} requested</span></span><input v-model.number="receiveForm.items[index].quantity" required type="number" min="1" max="9999" class="w-full border bg-white px-3 py-2 font-mono" /></label></div><FieldError :message="errorFor(receiveForm.errors as Record<string, string | undefined>, 'items', 'items.0.quantity', 'items.0.return_item_id') ?? serverErrors.quantity ?? serverErrors.return" /><button :disabled="receiveForm.processing" class="mt-4 bg-[#17211b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40">Receive all item lines</button></form>

        <section class="mt-10"><h2 class="text-3xl font-semibold">Return items</h2><div class="mt-5 grid gap-5"><article v-for="item in returnRequest.items" :key="item.id" class="border border-[#17211b]/15 bg-white p-5"><div class="flex flex-wrap items-start justify-between gap-5"><div><h3 class="text-xl font-semibold">{{ item.product_name }}</h3><p class="text-sm text-[#637067]">{{ item.variant_name ?? 'Default variant' }} / {{ item.sku }}</p><p v-if="item.reason" class="mt-2 text-sm">{{ item.reason }}</p></div><dl class="grid grid-cols-3 gap-5 text-center text-sm"><div><dt class="text-xs uppercase text-[#637067]">Requested</dt><dd class="mt-1 font-mono text-lg font-semibold">{{ item.requested_quantity }}</dd></div><div><dt class="text-xs uppercase text-[#637067]">Received</dt><dd class="mt-1 font-mono text-lg font-semibold">{{ item.received_quantity }}</dd></div><div><dt class="text-xs uppercase text-[#637067]">Accepted</dt><dd class="mt-1 font-mono text-lg font-semibold">{{ item.accepted_quantity }}</dd></div></dl></div>
                <div v-if="item.inspected_at" class="mt-5 grid gap-3 border-t pt-4 text-sm sm:grid-cols-4"><div><span class="text-[#637067]">Condition</span><p class="font-mono font-semibold">{{ item.condition }}</p></div><div><span class="text-[#637067]">Disposition</span><p class="font-mono font-semibold">{{ item.disposition }}</p></div><div><span class="text-[#637067]">Restocked</span><p class="font-mono font-semibold">{{ item.restocked_quantity }} / {{ item.accepted_quantity }}</p></div><div><span class="text-[#637067]">Notes</span><p>{{ item.inspection_notes ?? 'None' }}</p></div></div>
                <form v-if="capabilities.inspect && ['RECEIVED', 'INSPECTING'].includes(returnRequest.status)" class="mt-5 grid gap-4 border border-[#17211b]/15 bg-[#f8f5ed] p-4 sm:grid-cols-3" @submit.prevent="inspect(item)"><label class="text-sm font-semibold">Condition<select v-model="inspectForms[item.id].condition" required class="mt-2 w-full border bg-white px-3 py-2 font-normal"><option v-for="condition in conditions" :key="condition" :value="condition">{{ condition }}</option></select></label><label class="text-sm font-semibold">Disposition<select v-model="inspectForms[item.id].disposition" required class="mt-2 w-full border bg-white px-3 py-2 font-normal"><option v-for="disposition in dispositions" :key="disposition" :value="disposition">{{ disposition }}</option></select></label><label class="text-sm font-semibold">Accepted quantity<input v-model.number="inspectForms[item.id].accepted_quantity" required type="number" min="0" max="9999" class="mt-2 w-full border bg-white px-3 py-2 font-mono font-normal" /></label><label class="text-sm font-semibold sm:col-span-3">Inspection notes<textarea v-model="inspectForms[item.id].notes" maxlength="5000" class="mt-2 min-h-20 w-full border bg-white px-3 py-2 font-normal" /></label><div class="sm:col-span-3"><FieldError :message="errorFor(inspectForms[item.id].errors as Record<string, string | undefined>, 'condition', 'disposition', 'accepted_quantity', 'notes', 'item', 'return') ?? serverErrors.item" /><button :disabled="inspectForms[item.id].processing" class="mt-2 bg-[#17211b] px-4 py-2 text-sm font-semibold text-white disabled:opacity-40">{{ item.inspected_at ? 'Update inspection' : 'Record inspection' }}</button></div></form>
                <form v-if="capabilities.restock && returnRequest.status === 'INSPECTING' && item.disposition === 'RESTOCK' && item.accepted_quantity > item.restocked_quantity" class="mt-4 grid gap-4 border border-emerald-800/25 bg-emerald-50 p-4 sm:grid-cols-[1fr_8rem_auto] sm:items-end" @submit.prevent="restock(item)"><label class="text-sm font-semibold">Active location<select v-model="restockForms[item.id].inventory_location_id" required class="mt-2 w-full border bg-white px-3 py-2 font-normal"><option value="" disabled>Select a location</option><option v-for="location in locations" :key="location.id" :value="location.id">{{ location.code }} / {{ location.name }}</option></select></label><label class="text-sm font-semibold">Quantity<input v-model.number="restockForms[item.id].quantity" required type="number" min="1" max="9999" class="mt-2 w-full border bg-white px-3 py-2 font-mono font-normal" /></label><button :disabled="restockForms[item.id].processing || !locations.length" class="bg-emerald-800 px-4 py-2 text-sm font-semibold text-white disabled:opacity-40">Restock</button><FieldError class="sm:col-span-3" :message="errorFor(restockForms[item.id].errors as Record<string, string | undefined>, 'inventory_location_id', 'quantity', 'location', 'return') ?? serverErrors.quantity ?? serverErrors.location" /></form>
            </article></div></section>

        <div class="mt-10 grid gap-6 lg:grid-cols-2"><section class="border border-[#17211b]/15 bg-white p-6"><h2 class="text-2xl font-semibold">History</h2><ol class="mt-5 space-y-4"><li v-for="entry in returnRequest.history" :key="entry.id" class="border-l-2 border-emerald-700 pl-4"><p class="font-mono text-sm font-semibold">{{ entry.from_status ?? 'CREATED' }} → {{ entry.to_status }}</p><p class="mt-1 text-xs text-[#637067]">{{ entry.created_at ? new Date(entry.created_at).toLocaleString() : '—' }} / {{ entry.actor ?? 'System' }}</p><p v-if="entry.reason" class="mt-1 text-sm">{{ entry.reason }}</p></li></ol></section><section class="border border-[#17211b]/15 bg-white p-6"><h2 class="text-2xl font-semibold">Related exchanges</h2><div class="mt-5 grid gap-3"><Link v-for="exchange in exchanges" :key="exchange.id" :href="`/admin/exchanges/${exchange.id}`" class="border bg-[#f8f5ed] p-4"><div class="flex justify-between gap-3"><span class="font-mono font-semibold text-emerald-800">{{ exchange.short_id }}</span><span class="font-mono text-xs">{{ exchange.status }}</span></div><p class="mt-2 text-sm">{{ exchange.item_count }} replacement lines</p></Link><p v-if="!exchanges.length" class="text-sm text-[#637067]">No exchange is linked to this return.</p><form v-if="capabilities.create_exchange && exchangeForm.items.length && replacementVariants.length" class="mt-4 border border-emerald-800/25 bg-emerald-50 p-4" @submit.prevent="createExchange"><h3 class="font-semibold">Create exchange intent</h3><div v-for="(line, index) in exchangeForm.items" :key="line.return_item_id" class="mt-3 grid gap-2 sm:grid-cols-[1fr_6rem]"><select v-model="line.replacement_product_variant_id" required class="border bg-white px-3 py-2 text-sm"><option v-for="variant in replacementVariants" :key="variant.id" :value="variant.id">{{ variant.sku }} / {{ variant.product_name }} {{ variant.name ?? '' }}</option></select><input v-model.number="line.quantity" required type="number" min="1" max="9999" class="border bg-white px-3 py-2 font-mono" /><FieldError class="sm:col-span-2" :message="errorFor(exchangeForm.errors as Record<string, string | undefined>, `items.${index}.replacement_product_variant_id`, `items.${index}.quantity`)" /></div><FieldError :message="exchangeForm.errors.items" /><button :disabled="exchangeForm.processing" class="mt-4 bg-emerald-800 px-4 py-2 text-sm font-semibold text-white disabled:opacity-40">Create exchange</button></form><p v-else-if="capabilities.create_exchange" class="mt-4 border border-dashed p-4 text-sm text-[#637067]">Accepted return items and an active replacement variant are required.</p></div></section></div>
        <section v-if="refunds !== null" class="mt-8 border border-[#17211b]/15 bg-white p-6"><h2 class="text-2xl font-semibold">Related refunds</h2><div class="mt-5 grid gap-3 sm:grid-cols-2"><Link v-for="refund in refunds" :key="refund.id" :href="`/admin/refunds/${refund.id}`" class="border bg-[#f8f5ed] p-4"><div class="flex justify-between gap-3"><span class="font-mono font-semibold">{{ refund.currency }} {{ refund.amount }}</span><span class="font-mono text-xs">{{ refund.status }}</span></div><p class="mt-2 text-sm">{{ refund.reason }}</p></Link><p v-if="!refunds.length" class="text-sm text-[#637067]">No refund is linked to this return.</p></div></section>
        <div class="mt-10 grid gap-6 lg:grid-cols-2"><form v-if="capabilities.reject" class="border border-red-800/30 bg-red-50 p-6" @submit.prevent="reject"><h2 class="text-2xl font-semibold text-red-900">Reject request</h2><label class="mt-4 block text-sm font-semibold">Reason<textarea v-model="rejectForm.reason" required maxlength="500" class="mt-2 min-h-24 w-full border border-red-800/40 bg-white px-3 py-2" /></label><FieldError :message="rejectForm.errors.reason ?? serverErrors.return" /><button :disabled="rejectForm.processing" class="mt-4 border border-red-900 px-5 py-3 text-sm font-semibold text-red-900 disabled:opacity-40">Reject return</button></form><form v-if="capabilities.cancel" class="border border-amber-800/30 bg-amber-50 p-6" @submit.prevent="cancel"><h2 class="text-2xl font-semibold">Cancel return</h2><label class="mt-4 block text-sm font-semibold">Reason<textarea v-model="cancelForm.reason" required maxlength="500" class="mt-2 min-h-24 w-full border border-amber-800/40 bg-white px-3 py-2" /></label><FieldError :message="cancelForm.errors.reason ?? serverErrors.return" /><button :disabled="cancelForm.processing" class="mt-4 border border-[#17211b] px-5 py-3 text-sm font-semibold disabled:opacity-40">Cancel return</button></form></div>
    </section></AdminLayout>
</template>
